public class LongSerializer_serialize_TriageGen2Test {

    private NumberSerializers.LongSerializer serializer;
    private JsonGenerator gen;
    private SerializerProvider provider;

    @Before
    public void setUp() {
        serializer = new NumberSerializers.LongSerializer();
        gen = Mockito.mock(JsonGenerator.class);
        provider = Mockito.mock(SerializerProvider.class);
    }

    @Test
    public void testSerialize_withValidLong() throws IOException {
        // Arrange
        Long value = 12345L;

        // Act
        serializer.serialize(value, gen, provider);

        // Assert
        verify(gen).writeNumber(value.longValue());
    }








}

